// The almanac's events, January to June 1899 (Core/Almanac.cs has the logic). Each: key, year, month, day (the day it
// could be in the papers; 0: the month), where it mattered most (null the nation; west, high, south, world), how big
// (1-3), the kind, the paper's headline, the paper's sentence, and what one person thinks or says of it. The wording is
// this add-on's own; the facts and the dates are the year's. The lines keep to the harnesses' rules (110 characters,
// each naming its subject; in 1899 no telephone, no moving pictures, and the governor is "Teddy" in people's mouths).
namespace EnrageWestworld.Core
{
    public static partial class Almanac
    {
        private static readonly AlmanacEvent[] Events1899A =
        {
            // ---- January 1899 ----------------------------------------------------------------------------------
            E("cubahanded", 1899, 1, 1, null, 2, "world", "THE FLAG GOES UP OVER HAVANA",
              "Spain's rule in Cuba ended at noon on New Year's Day, and General Brooke took the island over as its military governor.",
              "Spain's gone from Cuba as of New Year's. Our flag over Havana now, and our soldiers under it.",
              "We own Cuba now, near enough. A year ago it was Remember the Maine. Things move fast with a navy."),
            E("rooseveltgov", 1899, 1, 2, null, 2, "politics", "ROOSEVELT TAKES THE OATH AT ALBANY",
              "Colonel Roosevelt of the Rough Riders was sworn in as Governor of New York, six months after the hill at Santiago.",
              "Teddy's governor of New York now. Last summer he was charging up a hill. The man don't sit still.",
              "They made the Rough Rider a governor. I'd like to see Platt's bosses tell that one what to do."),
            E("manhoe", 1899, 1, 16, null, 2, "life", "A POEM THAT HAS THE COUNTRY ARGUING",
              "A teacher named Markham printed a poem in a San Francisco paper about a man bowed over a hoe, and every paper in the land has copied it.",
              "Everybody's quoting that Man with the Hoe poem. Preacher read it Sunday like it was Scripture.",
              "A poem about a farmer at his hoe, and the rich men back East are writing the papers about it."),
            E("wakeisland", 1899, 1, 18, null, 1, "world", "ANOTHER ISLAND FOR THE UNITED STATES",
              "A navy gunboat raised the flag over Wake Island, a speck of sand in the Pacific, for a cable station on the road to Manila.",
              "We took another island. Wake, they call it. Nobody lives on it. We collect islands like boys collect stones.",
              "Wake Island's ours, for a telegraph cable to Manila. The whole Pacific's getting strung with wire."),
            E("malolos", 1899, 1, 24, null, 2, "world", "AGUINALDO PROCLAIMS HIS REPUBLIC",
              "The Filipino leader Aguinaldo had himself sworn in as president of a republic at Malolos, while our soldiers hold Manila under the treaty.",
              "Aguinaldo's made himself president of a Filipino republic. Two governments on one island. That'll end quiet.",
              "The Filipinos set up their own republic at Malolos. I thought freeing them was what we fought Spain for."),
            E("clarkseat", 1899, 1, 31, "high", 2, "politics", "CLARK ELECTED SENATOR AMID TALK OF MONEY",
              "The Montana legislature has sent the copper king W. A. Clark to the United States Senate, with the papers full of talk of what the votes cost him.",
              "Clark of Montana bought himself a Senate seat, they say. A thousand dollars a vote, if you credit Butte.",
              "Copper money buys a senator now. Daly's men are howling. Those two will spend Montana dry fighting."),
            E("beefcourt", 1899, 1, 13, null, 2, "politics", "THE EMBALMED BEEF QUARREL",
              "General Miles says the army fed the boys in Cuba embalmed beef, and Commissary General Eagan answered him before the commission in words the papers will not print.",
              "Embalmed beef. That's what they fed the boys in Cuba, General Miles says. Canned meat with chemicals in it.",
              "The army's own general says the boys ate rotten beef, and the packers call him a liar. The boys got sick."),
            E("hobsonkiss", 1899, 1, 0, null, 1, "life", "THE HERO OF THE MERRIMAC KISSED FROM COAST TO COAST",
              "Lieutenant Hobson, who sank the collier in the mouth of Santiago harbor, cannot pass a railroad town without the ladies lining up to kiss him.",
              "That Hobson fellow, the navy hero. Women kiss him by the hundred wherever his train stops.",
              "I'd sink a ship myself for the kissing Hobson gets. Every depot from here to Boston, the paper says."),
            E("hoarspeech", 1899, 1, 10, null, 1, "politics", "SENATOR HOAR AGAINST THE TREATY",
              "Old Senator Hoar of Massachusetts stood up against his own party to say a republic has no business ruling the Philippines without their consent.",
              "Senator Hoar says we've no right to the Philippines. His own party, too. Takes sand to say it in the Senate.",
              "Some senators don't want the islands at all. Say a republic can't own a people. I never thought of it so."),
            E("radium", 1899, 1, 0, "world", 1, "wonder", "A NEW ELEMENT THAT GIVES OFF RAYS",
              "The Paris chemists Curie say they have found a new element they call radium, which throws off rays of itself, stronger than uranium's, and never seems to tire.",
              "Two French chemists found a new element. Radium. Throws off rays all by itself, the paper says.",
              "Radium, they call it. A stuff that gives off rays and never tires. Sounds like a patent medicine to me."),
            E("roughridersbook", 1899, 1, 0, null, 1, "war", "THE COLONEL WRITES UP HIS REGIMENT",
              "Scribner's Magazine is running Governor Roosevelt's own account of the Rough Riders in Cuba, a chapter a month, and the newsstands sell out.",
              "Teddy's writing up the Rough Riders in Scribner's. A chapter a month. He's the hero of every one.",
              "Read the Rough Riders piece in the magazine. San Juan Hill, the way the colonel tells it. Stirring stuff."),
            // ---- February 1899 ---------------------------------------------------------------------------------
            E("manilafight", 1899, 2, 5, null, 3, "war", "FIGHTING BREAKS OUT AT MANILA",
              "Shooting began between our outposts and the Filipino army outside Manila on the night of the fourth, and the army calls it war.",
              "It's war in the Philippines now. Started Saturday night outside Manila. Our boys against Aguinaldo's.",
              "We beat Spain to free the Philippines, and now we're fighting the Filipinos. Explain that to me.",
              "Boys from this county are with the volunteers at Manila. I've been to the depot twice today for the wire."),
            E("treatyratified", 1899, 2, 7, null, 3, "politics", "THE SENATE RATIFIES THE TREATY WITH SPAIN",
              "By one vote more than the two thirds it needed, the Senate ratified the treaty that gives the United States the Philippines, Porto Rico and Guam.",
              "The Spanish treaty passed the Senate. One vote to spare. The Philippines are ours, like it or not.",
              "Bryan told his men to pass the treaty so he can fight the islands at the election. Clever, or foolish."),
            E("blizzard99", 1899, 2, 13, null, 3, "disaster", "THE GREAT COLD GRIPS THE WHOLE COUNTRY",
              "The worst cold in memory lies on the country from the plains to the Gulf; snow has fallen in Florida and ice floats out of the Mississippi into the sea.",
              "Coldest week anybody remembers. Snow in Florida, and ice floating down the river past New Orleans.",
              "Forty below in the Dakotas in the big cold. Cattle froze standing. Every ranch is counting its dead.",
              "The great cold killed the orange trees to the roots, they say. A winter to tell the grandchildren."),
            E("votingmachines", 1899, 2, 15, null, 1, "law", "CONGRESS ALLOWS THE VOTING MACHINE",
              "Congress has allowed voting machines in federal elections wherever a state will have them, in place of the paper ballot.",
              "Congress says machines can count the votes now. I'll trust a voting machine when it votes the way I did.",
              "Voting by machine, back East. Pull a lever and it's counted. Less work for the men who stuff the boxes."),
            E("faure", 1899, 2, 17, "world", 2, "death", "THE PRESIDENT OF FRANCE DEAD",
              "President Faure of France died suddenly at the Elysee palace; the deputies have chosen Loubet, and the Dreyfus quarrel goes on without him.",
              "The French president died all at once at his palace. The paper's careful about how. Paris is in uproar.",
              "France buried President Faure and picked another in two days. They change presidents like hats."),
            E("whitemansburden", 1899, 2, 6, null, 2, "world", "KIPLING WRITES A POEM FOR AMERICA",
              "Mr. Kipling's new verses, printed in McClure's, tell the United States what taking the Philippines will cost and call the work a burden.",
              "Kipling wrote us a poem about the Philippines. The white man's burden, he calls it. Easy said from England.",
              "Everybody's quoting Kipling's burden poem. Bryan's men call it an insult and McKinley's call it a sermon."),
            E("kiplingill", 1899, 2, 25, null, 2, "world", "KIPLING LIES ILL IN NEW YORK",
              "Rudyard Kipling is down with pneumonia at a New York hotel, and the whole country reads the doctors' bulletins every morning.",
              "Kipling's sick with pneumonia in New York, near to dying. Bulletins every day, like he was a president.",
              "Never read a line of Kipling, and I've asked twice today how he's doing. That's the papers for you."),
            E("canefreeze", 1899, 2, 16, "south", 2, "disaster", "THE FREEZE RUINS THE CANE AND THE ORANGES",
              "The February cold killed the sugar cane standing in Louisiana and the orange groves of Florida; planters say a year's crop is gone.",
              "The freeze took the cane. Every planter from here to the river is walking his fields, counting what's dead.",
              "Oranges dead in Florida, cane dead here. The sugar men will be borrowing from the banks they used to own."),
            E("mcteague", 1899, 2, 20, null, 1, "life", "A HARD NOVEL OF SAN FRANCISCO",
              "A young writer named Norris has a novel out about a San Francisco dentist who comes to a bad end, and the reviewers call it brutal and cannot put it down.",
              "New book about a dentist who comes to a bad end. McTeague. The ladies' club won't read it, so everybody does.",
              "The paper calls that San Francisco novel, McTeague, a low book. I'd like to know what a high book is."),
            // ---- March 1899 ------------------------------------------------------------------------------------
            E("rainierpark", 1899, 3, 3, "high", 1, "west", "A NATIONAL PARK AROUND MOUNT RAINIER",
              "Congress has set aside the great mountain of Washington State and the forests about it as a national park, after the pattern of the Yellowstone.",
              "They've made a national park of Mount Rainier. The government's collecting mountains now, like islands.",
              "Another national park, the paper says. Rainier. Soon the whole West will be fenced for tourists."),
            E("armyact", 1899, 3, 3, null, 2, "war", "A BIGGER ARMY FOR THE PHILIPPINES",
              "Congress has voted the regular army up to sixty-five thousand men, and thirty-five thousand volunteers besides, to be raised for the islands.",
              "Thirty-five thousand more volunteers for the Philippines. There'll be a recruiting sergeant in every town.",
              "Congress made the army sixty-five thousand strong. My grandfather said a standing army ends a republic."),
            E("josephinekipling", 1899, 3, 7, null, 1, "death", "KIPLING'S LITTLE DAUGHTER DEAD",
              "While Mr. Kipling fought for his own life, his daughter Josephine, six years old, died of the same pneumonia in New York.",
              "Kipling's little girl died while he was too sick to be told. Six years old. The paper ran it in black.",
              "All Kipling's fame, and he couldn't keep his own child alive. Money's no doctor."),
            E("aspirin", 1899, 3, 10, "world", 1, "wonder", "A NEW POWDER FOR THE HEADACHE",
              "A German chemical house has put out a powder it calls aspirin, said to bring down a headache or a fever without the sickness of the old remedies.",
              "There's a new powder from Germany for the head. Aspirin. Druggist says it beats the willow tea Ma used.",
              "Aspirin, the Germans call it. A fever powder that won't turn your stomach. The tonic men won't like it."),
            E("garcia", 1899, 3, 15, null, 2, "life", "A LITTLE ESSAY EVERY BOSS IS HANDING OUT",
              "A piece from a small magazine about a soldier who carried a message to Garcia without asking a question is printed by the hundred thousand for clerks and railroad men.",
              "The railroad gave every man that Message to Garcia piece. Do your job and don't ask why. I knew that already.",
              "My boss put the Garcia piece on the wall. Bosses love a story about a man who never asks why."),
            E("samoafight", 1899, 3, 16, "world", 1, "world", "OUR SHIPS FIRE ON SAMOA",
              "American and British warships have shelled the villages of a Samoan chief the Germans favor, over which king the islands shall have.",
              "We're shelling Samoa now, over which chief is king there. Three navies in one harbor over a few islands.",
              "Samoa. Had to find it in the atlas. Us and the British one side, the Germans the other, Samoans between."),
            E("windsorfire", 1899, 3, 18, null, 2, "disaster", "THE WINDSOR HOTEL BURNS ON FIFTH AVENUE",
              "The Windsor Hotel in New York burned to the ground in an hour while the St. Patrick's parade went past, with the crowd watching from the street.",
              "The Windsor Hotel burned in New York with the parade going past. People jumping from the windows, they say.",
              "The Windsor's gone. An hour and it was ash. All that stone and marble, and it burned like a haystack."),
            E("marconichannel", 1899, 3, 28, "world", 2, "wonder", "A MESSAGE ACROSS THE SEA WITHOUT A WIRE",
              "The Italian Marconi sent a telegraph message across the English Channel through the air alone, thirty-odd miles with no wire between.",
              "That Italian, Marconi, sent a telegram across the sea with no wire at all. Through the air. I can't see how.",
              "Wireless telegraph, they call it. Thirty miles over water. Next they'll be talking to ships at sea."),
            // ---- April 1899 ------------------------------------------------------------------------------------
            E("malolostaken", 1899, 4, 1, null, 2, "war", "OUR TROOPS TAKE THE FILIPINO CAPITAL",
              "General MacArthur's division marched into Malolos and found Aguinaldo's capital burning and empty; the Filipino army has fallen back north.",
              "We took the Filipino capital, Malolos. The paper calls it a victory, but Aguinaldo got away. What did we take?",
              "The boys marched into Malolos with the town on fire and Aguinaldo gone north. He'll not be caught easy."),
            E("smeltertrust", 1899, 4, 5, "high", 2, "money", "THE SMELTERS COMBINE INTO ONE COMPANY",
              "The smelting works of the West have been gathered into one company with sixty-five millions of capital, and the mining camps call it the smelter trust.",
              "They've made a trust of the smelters. One company for the ore of the Rockies. They set the price; we take it.",
              "The smelter trust. Every camp from Leadville to Butte sells to one buyer now. That's a toll gate."),
            E("strenuouslife", 1899, 4, 11, null, 2, "politics", "GOVERNOR ROOSEVELT PREACHES THE STRENUOUS LIFE",
              "In a speech at Chicago, Governor Roosevelt told the country that ease is a disgrace and that a nation, like a man, must take up hard work or rot.",
              "Teddy made a speech about the strenuous life. Work hard, fight hard, never rest. Easy for a rich man.",
              "The strenuous life, Teddy calls it. I've lived one since I was nine. Nobody made a speech about mine."),
            E("treatyforce", 1899, 4, 12, null, 1, "politics", "THE TREATY IS IN FORCE",
              "The ratifications were exchanged at Washington, and the treaty with Spain is law; the islands are ours on paper as they were already in fact.",
              "The Spanish treaty's official now. The Philippines, Porto Rico, Guam. Ours, signed and sealed.",
              "The treaty's the law now. I notice nobody asked the folks on the islands to sign it."),
            E("samoadead", 1899, 4, 13, null, 2, "war", "AMERICAN OFFICERS KILLED IN SAMOA",
              "A landing party of our sailors was ambushed in Samoa, and Lieutenant Lansdale and Ensign Monaghan died covering their men.",
              "Two navy officers killed on Samoa. The ensign stayed with his wounded lieutenant and died beside him.",
              "Sailors dying on Samoa, an island nobody wanted a year ago. The map gets bigger and the list longer."),
            E("juvenilecourtlaw", 1899, 4, 22, null, 1, "law", "ILLINOIS TO TRY CHILDREN APART FROM MEN",
              "Illinois has passed a law for a separate court for children under sixteen, so a boy who steals apples is not jailed beside a murderer.",
              "Illinois made a court just for children. A boy caught stealing goes there, not into the jail with the men.",
              "A children's court in Illinois. About time. Jail at twelve taught me more than any judge did."),
            E("awakening", 1899, 4, 24, "south", 1, "life", "A LOUISIANA NOVEL THE REVIEWERS CALL UNWHOLESOME",
              "Mrs. Chopin of St. Louis has a novel out about a Creole wife at Grand Isle who will not be a wife, and the reviewers are scandalized.",
              "A book about a Grand Isle wife who leaves her husband. The paper calls it poison. My wife's read it twice.",
              "Mrs. Chopin wrote a novel the critics won't have in the house. A Louisiana book, too. We're famous again."),
            E("quingua", 1899, 4, 25, "west", 2, "war", "COLONEL STOTSENBURG OF THE NEBRASKANS KILLED",
              "The First Nebraska lost its colonel at Quingua, shot leading his men across an open field; the Nebraskans took the town at a run.",
              "The Nebraska boys lost Colonel Stotsenburg. Led them across a field and took a bullet. Lincoln's in black.",
              "A Nebraska boy wrote home they ran the Filipinos out of Quingua after the colonel fell. Brave, and for what?"),
            E("kirksville", 1899, 4, 28, "west", 2, "disaster", "A CYCLONE WRECKS KIRKSVILLE",
              "A cyclone tore through Kirksville, Missouri, in the evening, wrecked the east side of the town and killed above thirty people.",
              "A cyclone took half of Kirksville, Missouri. Thirty dead. Houses lifted off their sills into the fields.",
              "That Missouri twister killed thirty-odd at Kirksville in a quarter hour. Makes you watch the evening sky."),
            E("calumpit", 1899, 4, 29, "west", 2, "war", "FUNSTON CROSSES THE RIVER UNDER FIRE",
              "Colonel Funston of the Twentieth Kansas got his men across the river at Calumpit under the Filipino guns, some swimming and some on a raft, and drove them out.",
              "Funston of the Kansas boys took his men over a river under fire at Calumpit. Some swam it. Little fellow, too.",
              "The Twentieth Kansas crossed a river on a raft under the Filipino guns. Kansas will build Funston a statue."),
            E("amalgamated", 1899, 4, 29, "high", 2, "money", "THE STANDARD OIL MEN BUY MONTANA COPPER",
              "Rogers and Rockefeller of the Standard Oil have joined Marcus Daly's Anaconda mines into an Amalgamated Copper company of seventy-five millions.",
              "The Standard Oil crowd bought into Montana copper. Amalgamated, they call it. Daly's in bed with Rockefeller.",
              "Seventy-five millions for Amalgamated Copper. Butte's owned from New York now, down to the last mule."),
            E("bunkerhill", 1899, 4, 30, "high", 3, "crime", "THE BUNKER HILL MILL BLOWN TO PIECES",
              "A thousand armed miners seized a train in the Coeur d'Alenes, rode it to Wardner, and blew up the Bunker Hill concentrator with dynamite.",
              "The miners in Idaho took a train and blew up the Bunker Hill mill. A thousand of them, masked. That's a war.",
              "They dynamited the Bunker Hill mill. The governor's sent for soldiers. Every miner up there will pay for it.",
              "Idaho again. The mine owners and the union have been at it since '92. Somebody's always blown up."),
            // ---- May 1899 --------------------------------------------------------------------------------------
            E("deweyday", 1899, 5, 1, null, 2, "world", "A YEAR SINCE MANILA BAY",
              "The first of May was kept as Dewey Day across the country, a year to the day since the Admiral sank the Spanish fleet before breakfast.",
              "Dewey Day. A year since he sank the Spanish at Manila. Flags on every store and a speech from every hat.",
              "A year ago today Dewey won the war in a morning. Took the rest of us a year to work out what he won."),
            E("derby99", 1899, 5, 5, "west", 1, "sport", "MANUEL WINS THE KENTUCKY DERBY",
              "Manuel took the Kentucky Derby at Louisville, and the men who backed him are buying the drinks from here to Chicago.",
              "Manuel won the Kentucky Derby. A horse named Manuel. I'd have bet on the name alone, if I'd had the money.",
              "Derby's run at Louisville. Manuel. Fellow at the livery had a dollar on him and won't stop telling it."),
            E("dawsonfire", 1899, 5, 8, "high", 1, "disaster", "DAWSON CITY BURNS",
              "Fire has burned the business streets of Dawson City in the Klondike to the ground, and the saloons and the banks with them.",
              "Dawson City burned, the paper says. Saloons, banks and all. The Klondike's got nothing left but the cold.",
              "Fire in Dawson. A town built of green logs in a winter that dry. It only wanted a stove tipped over."),
            E("wardnerbullpen", 1899, 5, 10, "high", 2, "law", "MARTIAL LAW IN THE COEUR D'ALENES",
              "Federal troops hold the Idaho mining country under martial law, and hundreds of miners are penned in a stockade at Wardner they call the bullpen.",
              "Soldiers have hundreds of Idaho miners in a stockade. The bullpen. No charge, no trial. Just a fence.",
              "They've put the Coeur d'Alene miners in a pen like stock. Martial law, the governor says, or more mills go up."),
            E("hagueopens", 1899, 5, 19, "world", 2, "world", "THE NATIONS MEET TO TALK OF PEACE",
              "The Czar's peace conference opened at The Hague with delegates from twenty-six nations, our own among them, to talk of smaller armies and the laws of war.",
              "The Czar called a peace meeting at The Hague. Every nation sending men, with the Philippines still shooting.",
              "They're at The Hague to make war gentler. Rules for it. I'd sooner they made it rarer."),
            E("teslasprings", 1899, 5, 20, "high", 2, "wonder", "TESLA BUILDS A LIGHTNING WORKS AT COLORADO SPRINGS",
              "The electrician Tesla has come to Colorado Springs to build a laboratory with a tall mast, and means to make lightning of his own in the thin air.",
              "That electrical man Tesla's building a tower at Colorado Springs to make lightning. Thunder on clear nights.",
              "Tesla's up in Colorado making lightning in a barn. Says he'll send power through the ground. Or burn the town."),
            E("speeding", 1899, 5, 22, null, 1, "law", "A CAB DRIVER ARRESTED FOR FURIOUS DRIVING",
              "A New York policeman on a bicycle ran down an electric cab doing twelve miles an hour on Lexington Avenue, and its driver spent the night in a cell.",
              "A policeman on a bicycle caught an electric cab doing twelve miles an hour in New York. Locked the driver up.",
              "Twelve miles an hour, and they jailed him for it. In New York they arrest the carriages now, not the drunks."),
            E("victoria80", 1899, 5, 25, "world", 1, "world", "QUEEN VICTORIA IS EIGHTY",
              "The old Queen kept her eightieth birthday at Windsor, sixty-two years on the throne, and the whole British empire lit bonfires for her.",
              "Queen Victoria's eighty. Queen since before my father was born. England can't picture the world without her.",
              "Eighty years old and still queen of England. Sixty-two years on the throne. Some constitution."),
            E("winton", 1899, 5, 28, null, 1, "wonder", "A HORSELESS CARRIAGE FROM CLEVELAND TO NEW YORK",
              "Mr. Winton of Cleveland has driven his own horseless carriage to New York, seven hundred miles in a few days, and the New York papers met him in the street.",
              "A Cleveland man drove his horseless carriage clear to New York. Seven hundred miles. The horses are worried.",
              "Winton, the carriage maker, drove from Cleveland to New York without a horse. I'll walk, thanks."),
            // ---- June 1899 -------------------------------------------------------------------------------------
            E("pearlhart", 1899, 6, 1, "west", 3, "crime", "A WOMAN HOLDS UP THE GLOBE STAGE",
              "The Globe stage was stopped in Arizona by two robbers, one a woman in men's clothes named Pearl Hart, who kept the passengers covered while her partner went through them.",
              "A woman robbed the stage in Arizona. In trousers, with a pistol. Pearl Hart. Every paper has her picture.",
              "Pearl Hart held up the Globe coach herself. Caught in days, and now she's more famous than the sheriff.",
              "A lady road agent in Arizona. My wife says good for her. I said what about the passengers. She shrugged."),
            E("harrimanalaska", 1899, 6, 2, "high", 1, "wonder", "A RAILROAD KING SAILS FOR ALASKA WITH THE PROFESSORS",
              "Mr. Harriman of the Union Pacific has taken a steamer full of scientists, John Muir among them, from Seattle to look at the coast of Alaska.",
              "Harriman took a boatload of professors up to Alaska to look at glaciers. Rich men holiday with scientists now.",
              "John Muir's gone north with Harriman to study the ice. There's a man who'd sooner have a mountain than money."),
            E("wilcox", 1899, 6, 3, "west", 3, "crime", "THE OVERLAND FLYER ROBBED AT WILCOX",
              "Masked men stopped the Union Pacific's Overland Flyer near Wilcox, Wyoming, before dawn, blew open the express car with dynamite and rode north with the money.",
              "They robbed the Overland Flyer at Wilcox. Used so much dynamite the money blew all over the prairie.",
              "Six men robbed the Overland Flyer in Wyoming and rode off rich. Posses out from Casper. Good luck to them.",
              "Hole-in-the-Wall men robbed that Wilcox train, they're saying. The express company's offering thousands."),
            E("strauss", 1899, 6, 4, "world", 1, "death", "THE WALTZ KING IS DEAD",
              "Johann Strauss, who wrote the Blue Danube and taught the world to waltz, died at Vienna in his seventy-fourth year.",
              "Strauss died, the waltz man. Every fiddler in the country owes him a living and never paid a cent.",
              "The Blue Danube fellow's dead in Vienna. My wife and I danced to that at our wedding. Feels like a door shut."),
            E("dreyfusretrial", 1899, 6, 4, "world", 2, "world", "FRANCE TO TRY DREYFUS AGAIN",
              "The highest court of France has thrown out the conviction of Captain Dreyfus and ordered him brought back from Devil's Island for a new trial.",
              "Dreyfus is coming back from Devil's Island for a new trial. Four years on a rock for a letter he didn't write.",
              "Dreyfus gets another trial. All France is fighting over one Jewish officer. The paper's full of nothing else."),
            E("boertalks", 1899, 6, 6, "world", 1, "world", "KRUGER AND MILNER MEET AT BLOEMFONTEIN",
              "Old President Kruger of the Transvaal and the British governor met at Bloemfontein over the rights of the foreigners in the gold fields, and parted with nothing settled.",
              "The British and the Boers are talking in Africa about who votes in the gold country. Talking, for now.",
              "Kruger won't let the English miners vote and the English won't let it go. There's a war in that, I'd say."),
            E("hazen", 1899, 6, 6, "west", 2, "crime", "SHERIFF HAZEN SHOT BY THE TRAIN ROBBERS",
              "Sheriff Hazen of Converse County came up with the Wilcox robbers in the broken country north of Casper and was shot dead from the rocks.",
              "The Wilcox robbers shot Sheriff Hazen from the rocks. He got closer to them than the Pinkertons ever will.",
              "Hazen's dead. Good sheriff, they say. Rode after the train robbers with a handful of men. They were waiting."),
            E("jeffriesfitz", 1899, 6, 10, null, 3, "sport", "JEFFRIES IS CHAMPION OF THE WORLD",
              "The boilermaker Jeffries knocked out Fitzsimmons in the eleventh round at Coney Island and is heavyweight champion at twenty-four.",
              "Jeffries beat Fitzsimmons in the eleventh round. The boilermaker's champion of the world, and twenty-four.",
              "Fitz is done. Jeffries took everything he had for ten rounds and put him down in the eleventh.",
              "A boilermaker champion of the world. Jeffries. Every man in the saloon's an expert on the eleventh round."),
            E("clevelandstrike", 1899, 6, 12, null, 1, "law", "THE CLEVELAND CAR STRIKE TURNS UGLY",
              "The streetcar men of Cleveland are out against the Big Consolidated, the company runs the cars with new men, and the crowds stone them in the streets.",
              "The Cleveland streetcar men struck, and the crowds are stoning the cars the company runs without them.",
              "Car strike in Cleveland. Folks walking to work rather than ride with the new men. Some are throwing bricks."),
            E("newrichmond", 1899, 6, 13, "west", 2, "disaster", "A TORNADO DESTROYS NEW RICHMOND",
